import java.io.*;
import java.util.*;

public class Main {
    static final long INF = 1L << 28;
    static final long MOD = 1000000007L;

    static long POWER(long base, long expo) {
        long num = 1;
        long i = expo;
        while (i != 0) {
            num = num * base;
            i--;
        }
        return num;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizerLike in = new StreamTokenizerLike(br);
        StringBuilder sb = new StringBuilder();

        long t = 1; // t = in.nextLong();
        while (t-- > 0) {
            long n = in.nextLong(), m = in.nextLong(), k = in.nextLong();
            long[] a = new long[(int) n];
            for (int i = 0; i < n; i++)
                a[i] = in.nextLong();
            Arrays.sort(a);
            if (m <= k) sb.append(0);
            else {
                long sum = 0, i = n, devices = m, soc = k;
                while (sum < m && devices > soc && i >= 1) {
                    i--;
                    sum += a[(int) i];
                    devices -= a[(int) i];
                    soc--;
                }
                if (devices <= soc) sb.append(n - i);
                else {
                    long i2 = n, used = 0, ss = 0, j = 0;
                    while (i2 >= 1 && ss < m) {
                        i2--;
                        if (used >= k * j && j >= 1)
                            ss--;
                        ss += a[(int) i2];
                        used++;
                        if (used % k == 0 && used != 0)
                            j++;
                    }
                    if (ss >= m) sb.append(used);
                    else sb.append(-1);
                }
            }
        }
        System.out.print(sb);
    }

    static class StreamTokenizerLike {
        BufferedReader br;
        StringTokenizer st;

        StreamTokenizerLike(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}
